// Generated by `npm run toolkits:sync` in the CMS repository (toolkits/client). Do not edit here.
// Rich text safety.
//
// A `richtext` field arrives as HTML the CMS already sanitized (an allow list of
// tags and attributes, http/https/mailto/tel links only, no scripts, no event
// handlers, no inline styles): see RICH_TEXT in cms/server/src/delivery/serialize.ts.
// It is safe to inject as HTML (Astro `set:html`, React `dangerouslySetInnerHTML`,
// Vue `v-html`, PHP echo) as long as these rules hold:
//
// 1. Only inject values that came from a richtext field of the delivery API.
//    Plain `text` and `textarea` fields are NOT sanitized: escape them, or let the
//    template engine escape them (that is the default everywhere).
// 2. Never request `richtext=markdown` and render the markdown yourself without a
//    sanitizer: the markdown allows raw HTML.
// 3. Never concatenate user input (query strings, form values) into that HTML.
// 4. Links in rich text may be external: the CMS keeps `target` and `rel` as the
//    editor set them. `withExternalRel` adds rel="noopener" to target="_blank" links
//    when a site wants that guarantee regardless of the editor's input.

/** Whether a value is HTML the CMS produced for a richtext field (a string; empty counts as nothing to render). */
export const hasRichText = (value: unknown): value is string => typeof value === "string" && value.trim().length > 0;

/** Adds rel="noopener noreferrer" to every target="_blank" link that lacks it. */
export function withExternalRel(html: string) {
  return html.replace(/<a\b[^>]*target="_blank"[^>]*>/gi, (tag) => {
    if (/\brel="[^"]*noopener/i.test(tag)) return tag;
    const rel = /\brel="([^"]*)"/i.exec(tag);
    if (rel) return tag.replace(rel[0], `rel="${rel[1]} noopener noreferrer"`.replace('rel=" ', 'rel="'));
    return tag.replace(/^<a\b/i, '<a rel="noopener noreferrer"');
  });
}

/** Strips tags from a rich text (an excerpt, a meta description), collapsing whitespace. */
export function plainText(html: string, maxLength?: number) {
  const text = html
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, " ")
    .trim();
  if (maxLength === undefined || text.length <= maxLength) return text;
  return `${text.slice(0, maxLength).replace(/\s+\S*$/, "")}…`;
}

/** Escapes text for an HTML attribute or text node (for the fields the CMS does not sanitize). */
export const escapeHtml = (value: unknown) => String(value ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
